window.products.push({"id":1132514,"name":"Oatey LO-VOC X-15™ PVC Solvent","category":"homeandappliances","retail price":49.79,"sale price":null,"image":"https://m.media-amazon.com/images/I/91w+589k6AL._AC_SL1500_.jpg","description":"Oatey LO-VOC X-15™ PVC Bonding Adhesive provides a permanent, watertight seal when joining flexible PVC membrane sheets together. The adhesive is ideal for use in tile showers and other concealed water-proofing applications, adhering shower pan liner seams together and dam corners over the shower curb. This fast-acting adhesive creates a strong, lasting bond. Oatey products have earned the trust of plumbing professionals for over 100 years.","images":["https://m.media-amazon.com/images/I/91w+589k6AL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Oatey","source_asin":"B00YDFSC1M","category_path":"Home & Kitchen"},"sku":"BM-1132514","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00YDFSC1M","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00YDFSC1M","price_pending":true,"merchant_ready":false});
